384	\begin{lemma}[Preservation of the robustness error family]\label{lem:qld-extraction-error-form}
385		\lean{MIPStarRE.QPBT.deltaExtract_le_deltaQld}
386		\uses{def:admissible, lem:qld-unitary}
387		Let $C\geq1$, $a>1$, and $0<b<1$. Suppose that
388		\[
389			\delta_G=a(md)^a\bigl(\eps^b+q^{-b}+2^{-bmd}\bigr),
390			\qquad
391			\delta_P=C\left(\delta_G+\sqrt{\eps}+\frac{md}{q}\right),
392		\]
393		and set $\delta_{\mathrm{ext}}=C(\delta_P^{1/4}+md/q)$. There are constants
394		$a'\geq1$ and $0<b'<1$, depending only on $C,a,b$, such that, for every
395		admissible $(q,m,d)$ and every $0\leq\eps\leq1$,
396		\[
397			\delta_{\mathrm{ext}}
398			\leq a'(md)^{a'}\bigl(\eps^{b'}+q^{-b'}+2^{-b'md}\bigr).
399		\]
400	\end{lemma}
